--
-- Name: assign_incident_to_user(integer, text); Type: FUNCTION; Schema: app; Owner: app_owner
--

CREATE FUNCTION app.assign_incident_to_user(p_incident_id integer, p_user_login text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'ref', 'audit'
    AS $$
DECLARE
    v_user_id       INT;
    v_status_name   TEXT;
    v_input_params  JSONB;
BEGIN
    v_input_params := jsonb_build_object(
        'incident_id', p_incident_id,
        'user_login', p_user_login
    );

    -- 1. инцидент существует
    SELECT s.name INTO v_status_name
    FROM app.incidents i
    JOIN ref.incident_statuses s ON s.id = i.status_id
    WHERE i.id = p_incident_id;

    IF v_status_name IS NULL THEN
        RAISE EXCEPTION 'Инцидент с ID=% не найден', p_incident_id;
    END IF;

    -- 2. инцидент не в конечном статусе
    IF v_status_name IN ('Closed', 'False Positive', 'Resolved') THEN
        RAISE EXCEPTION 'Нельзя назначить исполнителя на инцидент в статусе "%"', v_status_name;
    END IF;

    -- 3. пользователь существует
    SELECT id INTO v_user_id FROM app.users
    WHERE username = p_user_login AND is_active = TRUE;
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Пользователь "%" не найден или неактивен', p_user_login;
    END IF;

    -- 4. обновляем
    UPDATE app.incidents
       SET assignee_id = v_user_id,
           updated_at  = now()
     WHERE id = p_incident_id;

    -- 5. логирование успеха
    PERFORM audit.log_function_call('app.assign_incident_to_user', v_input_params, TRUE, NULL);
    RETURN 'Исполнитель "' || p_user_login || '" назначен на инцидент ID=' || p_incident_id;

EXCEPTION WHEN OTHERS THEN
    -- 6. логирование ошибки
    PERFORM audit.log_function_call('app.assign_incident_to_user', v_input_params, FALSE, SQLERRM);
    RETURN 'ОШИБКА: ' || SQLERRM;
END;
$$;


ALTER FUNCTION app.assign_incident_to_user(p_incident_id integer, p_user_login text) OWNER TO app_owner;

