-- Name: FUNCTION assign_incident_to_user(p_incident_id integer, p_user_login text); Type: COMMENT; Schema: app; Owner: app_owner
--

COMMENT ON FUNCTION app.assign_incident_to_user(p_incident_id integer, p_user_login text) IS 'Назначение исполнителя на инцидент с проверкой статуса и активности пользователя';


--
-- Name: change_incident_status(integer, text, text); Type: FUNCTION; Schema: app; Owner: app_owner
--

CREATE FUNCTION app.change_incident_status(p_incident_id integer, p_new_status_name text, p_assignee_login text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'ref', 'audit'
    AS $$
DECLARE
    v_current_status_id   INT;
    v_current_status_name TEXT;
    v_new_status_id       INT;
    v_assignee_id         INT;
    v_input_params        JSONB;
BEGIN
    v_input_params := jsonb_build_object(
        'incident_id', p_incident_id,
        'new_status_name', p_new_status_name,
        'assignee_login', p_assignee_login
    );

    -- 1. инцидент существует
    SELECT i.status_id, s.name INTO v_current_status_id, v_current_status_name
    FROM app.incidents i
    JOIN ref.incident_statuses s ON s.id = i.status_id
    WHERE i.id = p_incident_id;

    IF v_current_status_id IS NULL THEN
        RAISE EXCEPTION 'Инцидент с ID=% не найден', p_incident_id;
    END IF;

    -- 2. новый статус существует
    SELECT id INTO v_new_status_id FROM ref.incident_statuses WHERE name = p_new_status_name;
    IF v_new_status_id IS NULL THEN
        RAISE EXCEPTION 'Статус "%" не существует', p_new_status_name;
    END IF;

    -- 3. конечные статусы не меняются
    IF v_current_status_name IN ('Closed', 'False Positive') THEN
        RAISE EXCEPTION 'Нельзя изменить конечный статус "%"', v_current_status_name;
    END IF;

    -- 4. дубликат статуса
    IF v_current_status_id = v_new_status_id THEN
        RAISE EXCEPTION 'Инцидент уже находится в статусе "%"', v_current_status_name;
    END IF;

    -- 5. исполнитель существует
    IF p_assignee_login IS NOT NULL THEN
        SELECT id INTO v_assignee_id FROM app.users
        WHERE username = p_assignee_login AND is_active = TRUE;
        IF v_assignee_id IS NULL THEN
            RAISE EXCEPTION 'Пользователь "%" не найден или неактивен', p_assignee_login;
        END IF;
    END IF;

    -- 6. Resolved требует исполнителя
    IF p_new_status_name = 'Resolved'
       AND v_assignee_id IS NULL
       AND NOT EXISTS (SELECT 1 FROM app.incidents
                       WHERE id = p_incident_id AND assignee_id IS NOT NULL) THEN
        RAISE EXCEPTION 'Нельзя перевести инцидент в статус "Resolved" без исполнителя';
    END IF;

    -- 7. обновляем
    UPDATE app.incidents
       SET status_id   = v_new_status_id,
           assignee_id = COALESCE(v_assignee_id, assignee_id),
           updated_at  = now(),
           resolved_at = CASE WHEN p_new_status_name = 'Resolved' THEN now() ELSE resolved_at END
     WHERE id = p_incident_id;

    -- 8. логирование успеха
    PERFORM audit.log_function_call('app.change_incident_status', v_input_params, TRUE, NULL);
    RETURN 'Статус инцидента ID=' || p_incident_id || ' успешно изменён на "' || p_new_status_name || '"';

EXCEPTION WHEN OTHERS THEN
    -- 9. логирование ошибки
    PERFORM audit.log_function_call('app.change_incident_status', v_input_params, FALSE, SQLERRM);
    RETURN 'ОШИБКА: ' || SQLERRM;
END;
$$;


ALTER FUNCTION app.change_incident_status(p_incident_id integer, p_new_status_name text, p_assignee_login text) OWNER TO app_owner;

--
-- Name: FUNCTION change_incident_status(p_incident_id integer, p_new_status_name text, p_assignee_login text); Type: COMMENT; Schema: app; Owner: app_owner
--

COMMENT ON FUNCTION app.change_incident_status(p_incident_id integer, p_new_status_name text, p_assignee_login text) IS 'Смена статуса инцидента с проверкой бизнес-правил: конечные статусы, дубликаты, Resolved без исполнителя';


--
-- Name: get_current_segment_id(); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.get_current_segment_id() RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'app', 'ref', 'public'
    AS $$
DECLARE
    v_raw     TEXT;
    v_segment INT;
BEGIN
    v_raw := current_setting('app.current_segment_id', TRUE);

    IF v_raw IS NOT NULL AND v_raw <> '' THEN
        v_segment := v_raw::INT;
    END IF;

    IF v_segment IS NULL THEN
        SELECT segment_id INTO v_segment
        FROM app.users
        WHERE username = current_user;
    END IF;

    RETURN v_segment;
END;
$$;


ALTER FUNCTION app.get_current_segment_id() OWNER TO postgres;

--
-- Name: register_incident(text, text, text, text, text, integer[]); Type: FUNCTION; Schema: app; Owner: app_owner
--

CREATE FUNCTION app.register_incident(p_title text, p_description text, p_category_name text, p_priority_name text, p_reporter_login text, p_asset_ids integer[] DEFAULT NULL::integer[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'ref', 'audit'
    AS $$
DECLARE
    v_incident_id   INT;
    v_category_id   INT;
    v_priority_id   INT;
    v_status_id     INT;
    v_reporter_id   INT;
    v_asset_id      INT;
    v_input_params  JSONB;
BEGIN
    v_input_params := jsonb_build_object(
        'title', p_title, 'description', p_description,
        'category_name', p_category_name, 'priority_name', p_priority_name,
        'reporter_login', p_reporter_login, 'asset_ids', p_asset_ids
    );

    -- 1. title не пустой
    IF p_title IS NULL OR length(trim(p_title)) = 0 THEN
        RAISE EXCEPTION 'Название инцидента не может быть пустым';
    END IF;

    -- 2. description не пустой
    IF p_description IS NULL OR length(trim(p_description)) = 0 THEN
        RAISE EXCEPTION 'Описание инцидента не может быть пустым';
    END IF;

    -- 3. категория существует
    SELECT id INTO v_category_id FROM ref.incident_categories WHERE name = p_category_name;
    IF v_category_id IS NULL THEN
        RAISE EXCEPTION 'Категория "%" не найдена', p_category_name;
    END IF;

    -- 4. приоритет существует
    SELECT id INTO v_priority_id FROM ref.incident_priorities WHERE name = p_priority_name;
    IF v_priority_id IS NULL THEN
        RAISE EXCEPTION 'Приоритет "%" не найден', p_priority_name;
    END IF;

    -- 5. автор существует
    SELECT id INTO v_reporter_id FROM app.users WHERE username = p_reporter_login AND is_active = TRUE;
    IF v_reporter_id IS NULL THEN
        RAISE EXCEPTION 'Пользователь "%" не найден или неактивен', p_reporter_login;
    END IF;

    -- 6. статус New существует
    SELECT id INTO v_status_id FROM ref.incident_statuses WHERE name = 'New';
    IF v_status_id IS NULL THEN
        RAISE EXCEPTION 'Статус "New" не найден';
    END IF;

    -- 7. создаём инцидент
    RETURNING id INTO v_incident_id;

    -- 8. привязка активов
    IF p_asset_ids IS NOT NULL AND array_length(p_asset_ids, 1) > 0 THEN
        FOREACH v_asset_id IN ARRAY p_asset_ids LOOP
            IF NOT EXISTS (SELECT 1 FROM app.assets WHERE id = v_asset_id) THEN
                RAISE EXCEPTION 'Актив с ID=% не существует', v_asset_id;
            END IF;
            VALUES (v_incident_id, v_asset_id);
        END LOOP;
    END IF;

    -- 9. логирование успеха
    PERFORM audit.log_function_call('app.register_incident', v_input_params, TRUE, NULL);
    RETURN v_incident_id;

EXCEPTION WHEN OTHERS THEN
    -- 10. логирование ошибки
    PERFORM audit.log_function_call('app.register_incident', v_input_params, FALSE, SQLERRM);
    RETURN NULL;
END;
$$;


ALTER FUNCTION app.register_incident(p_title text, p_description text, p_category_name text, p_priority_name text, p_reporter_login text, p_asset_ids integer[]) OWNER TO app_owner;

--
-- Name: FUNCTION register_incident(p_title text, p_description text, p_category_name text, p_priority_name text, p_reporter_login text, p_asset_ids integer[]); Type: COMMENT; Schema: app; Owner: app_owner
--

COMMENT ON FUNCTION app.register_incident(p_title text, p_description text, p_category_name text, p_priority_name text, p_reporter_login text, p_asset_ids integer[]) IS 'Регистрация нового инцидента ИБ: создаёт запись в app.incidents, привязывает активы, пишет в audit.function_calls';


--
-- Name: request_temp_privilege(text, integer); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.request_temp_privilege(p_operation text, p_duration_min integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'audit'
    AS $$
DECLARE
    v_expires TIMESTAMPTZ;
    v_allowed BOOLEAN;
BEGIN
    IF NOT pg_has_role(session_user, 'app_writer', 'MEMBER') THEN
        RAISE EXCEPTION 'Доступ запрещён: только app_writer может запрашивать привилегии';
    END IF;

    SELECT (p_operation IN ('DELETE_INCIDENT', 'UPDATE_INCIDENT'))
    INTO v_allowed;

    IF NOT v_allowed THEN
        RAISE EXCEPTION 'Операция % не разрешена для JIT-запроса', p_operation;
    END IF;

    v_expires := now() + (p_duration_min || ' minutes')::INTERVAL;


    RETURN format('Привилегия %s выдана до %s', p_operation, v_expires);
END;
$$;


ALTER FUNCTION app.request_temp_privilege(p_operation text, p_duration_min integer) OWNER TO postgres;

--
-- Name: set_session_ctx(integer, integer); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.set_session_ctx(p_actor_id integer, p_segment_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'app', 'ref', 'public'
    AS $$
DECLARE
    v_ok BOOLEAN;
BEGIN
    SET LOCAL row_security = off;

    SELECT EXISTS (
        SELECT 1 FROM app.users
        WHERE id = p_actor_id
          AND segment_id = p_segment_id
          AND is_active = TRUE
    ) INTO v_ok;

    IF v_ok THEN
        PERFORM set_config('app.current_segment_id', p_segment_id::TEXT, FALSE);
        PERFORM set_config('app.current_actor_id', p_actor_id::TEXT, FALSE);
    ELSE
        RAISE EXCEPTION 'Пользователь % не принадлежит сегменту %', p_actor_id, p_segment_id;
    END IF;
END;
$$;


ALTER FUNCTION app.set_session_ctx(p_actor_id integer, p_segment_id integer) OWNER TO postgres;

--
-- Name: backup_audit_logs(integer); Type: FUNCTION; Schema: audit; Owner: postgres
--

CREATE FUNCTION audit.backup_audit_logs(days_interval integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'audit'
    AS $$
DECLARE
    v_count INT;
BEGIN
    WITH moved AS (
        DELETE FROM audit.row_change_log
        WHERE change_time < (now() - (days_interval || ' days')::INTERVAL)
        RETURNING *
    )
    SELECT * FROM moved;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN format('Перенесено %s записей старше %s дней', v_count, days_interval);
END;
$$;


ALTER FUNCTION audit.backup_audit_logs(days_interval integer) OWNER TO postgres;

--
-- Name: check_temp_privilege(text); Type: FUNCTION; Schema: audit; Owner: postgres
--

CREATE FUNCTION audit.check_temp_privilege(p_operation text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'audit'
    AS $$
DECLARE
    v_exists BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM audit.temp_access_log
        WHERE caller_role = session_user
          AND operation = p_operation
          AND expires_at > now()
          AND status = 'active'
    ) INTO v_exists;
    RETURN v_exists;
END;
$$;


ALTER FUNCTION audit.check_temp_privilege(p_operation text) OWNER TO postgres;

