--
-- Name: trg_log_changes(); Type: FUNCTION; Schema: audit; Owner: postgres
--

CREATE FUNCTION audit.trg_log_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'audit'
    AS $$
DECLARE
    v_old JSONB;
    v_new JSONB;
    v_id  TEXT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_id  := OLD.id::TEXT;
        v_old := to_jsonb(OLD);
        v_new := NULL;
    ELSE
        v_id  := NEW.id::TEXT;
        v_old := to_jsonb(OLD);
        v_new := to_jsonb(NEW);
    END IF;

    IF TG_TABLE_NAME = 'users' THEN
        IF v_old IS NOT NULL THEN
            v_old := v_old || '{"password_hash": "***MASKED***", "phone": "***MASKED***"}'::JSONB;
        END IF;
        IF v_new IS NOT NULL THEN
            v_new := v_new || '{"password_hash": "***MASKED***", "phone": "***MASKED***"}'::JSONB;
        END IF;
    END IF;

    IF TG_TABLE_NAME = 'threat_intelligence' THEN
        IF v_old IS NOT NULL THEN
            v_old := v_old || '{"indicator_value": "***MASKED***"}'::JSONB;
        END IF;
        IF v_new IS NOT NULL THEN
            v_new := v_new || '{"indicator_value": "***MASKED***"}'::JSONB;
        END IF;
    END IF;


    RETURN NULL;
END;
$$;


ALTER FUNCTION audit.trg_log_changes() OWNER TO postgres;

--
-- Name: trg_require_temp_privilege(); Type: FUNCTION; Schema: audit; Owner: postgres
--

CREATE FUNCTION audit.trg_require_temp_privilege() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'audit'
    AS $$
BEGIN
    IF NOT audit.check_temp_privilege('DELETE_INCIDENT') THEN
        RAISE EXCEPTION 'JIT: нет активной временной привилегии на удаление';
    END IF;
    RETURN OLD;
END;
$$;


ALTER FUNCTION audit.trg_require_temp_privilege() OWNER TO postgres;

