CREATE VIEW app.v_segment_incident_stats WITH (security_barrier='true') AS
 SELECT s.name AS segment_name,
    count(i.id) AS incidents_count,
    count(DISTINCT i.assignee_id) AS assignees_count,
    count(DISTINCT i.category_id) AS categories_count
   FROM (app.incidents i
     JOIN ref.segments s ON ((s.id = i.segment_id)))
  GROUP BY s.name;


