-- Name: incident_assets; Type: ROW SECURITY; Schema: app; Owner: app_owner
--

ALTER TABLE app.incident_assets ENABLE ROW LEVEL SECURITY;

--
-- Name: incident_assets incident_assets_isolation_policy; Type: POLICY; Schema: app; Owner: app_owner
--

CREATE POLICY incident_assets_isolation_policy ON app.incident_assets USING ((EXISTS ( SELECT 1
   FROM app.incidents i
  WHERE ((i.id = incident_assets.incident_id) AND (i.segment_id = app.get_current_segment_id()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM app.incidents i
  WHERE ((i.id = incident_assets.incident_id) AND (i.segment_id = app.get_current_segment_id())))));


